	static readonly int V4_SYMBOL_NAME_COL = 0;
	static readonly int V4_SYMBOL_ADDR_COL = 1;
	static readonly int V4_SYMBOL_PARENT_ID_COL = 2;
	static readonly int V4_SYMBOL_TYPE_COL = 3;
	static readonly int V4_SYMBOL_FLAGS_COL = 4;

	// Sparse fields - the following fields are not always applicable so they are optional and 
