	static readonly int V4_SYMBOL_HASH_COL = 5;
	static readonly int V4_SYMBOL_PRIMARY_COL = 6;
	static readonly int V4_SYMBOL_DATATYPE_COL = 7;
	static readonly int V4_SYMBOL_VAROFFSET_COL = 8;
	static readonly int V4_SYMBOL_ORIGINAL_IMPORTED_NAME_COL = 9;
